package fraymus.workspace;

import org.json.*;

/** A dated, escaped snapshot of actual runtime evidence, never a live truth claim. */
final class AgentReport042 {
    static JSONObject build(JSONObject state,String hash){
        StringBuilder rows=new StringBuilder();for(Object raw:state.getJSONArray("recentWitnesses")){var r=(JSONObject)raw;rows.append("<tr><td>").append(KnowledgeReport.escape(r.getString("kind"))).append("</td><td>").append(KnowledgeReport.escape(r.getJSONObject("evidence").optString("wallTime"))).append("</td><td>").append(r.getString("hash")).append("</td></tr>");}
        String html="<!doctype html><html lang=en><meta charset=utf-8><meta name=viewport content='width=device-width,initial-scale=1'><title>Continuing Java agent042</title><style>*{box-sizing:border-box}body{margin:0;padding:28px;background:#10242b;color:#e4f1ed;font:16px/1.6 system-ui;overflow-wrap:anywhere}article{max-width:1100px;margin:auto}section{padding:20px;background:#19383e;border-radius:15px;margin:16px 0}pre{white-space:pre-wrap}table{width:100%;border-collapse:collapse}td,th{padding:8px;text-align:left;border-bottom:1px solid #547069}@media(max-width:600px){body{padding:12px}section{padding:12px}}</style><article><p>FRAYNIX / JAVA CONTINUITY042</p><h1>One agent. A continuing runtime.</h1><p id=agent042-hash>"+hash+"</p><section><h2>Identity and clocks</h2><p id=agent042-id>"+state.getString("agentId")+"</p><p id=agent042-boot>"+state.getString("bootId")+"</p><p>Status: "+state.getString("status")+" · decision: "+state.getString("decision")+"</p><p>Retained active time: "+state.getJSONObject("clock").getLong("retainedActiveMs")+" ms · logical ticks: "+state.getJSONObject("clock").getLong("logicalTicks")+"</p></section><section><h2>Recent witnessed events</h2><table><thead><tr><th>Event</th><th>Wall time</th><th>Integrity hash</th></tr></thead><tbody id=agent042-events>"+rows+"</tbody></table></section><section><h2>Source, neural and appraisal evidence</h2><pre>"+KnowledgeReport.escape(state.toString(2))+"</pre></section><p>This is a saved dated snapshot. The witness verifies record integrity, not source truth. Sensory plasticity/replay is computation; policy improvements require separate held-out outcome tests. No subjective feeling, semantic recognition or LLM weight training is established.</p><p><a href=snapshot.json>Exact snapshot JSON</a></p></article></html>";
        return new JSONObject().put("title","Continuing Java agent042").put("files",new JSONObject().put("index.html",html).put("snapshot.json",state.toString(2)).put("receipt.json",new JSONObject().put("snapshotSha256",hash).toString()));
    }
}
